}

function card(slide, x, y, w, h, opts={}) {
  slide.addShape(pptx.ShapeType.roundRect, {
    x, y, w, h,
    rectRadius: 0.08,
    fill: { color: opts.fill || C.paper, transparency: opts.transparency || 0 },
    line: { color: opts.line || 'E4EAF3', width: opts.lineWidth || 1 },
    shadow: opts.shadow === false ? undefined : { type: 'outer', color: '0B1220', opacity: 0.08, blur: 1, angle: 45, distance: 1 }
  });
}

function pill(slide, x, y, w, text, color, opts={}) {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h: opts.h || 0.22, rectRadius: 0.06, fill: { color, transparency: opts.transparency || 0 }, line: { color, transparency: opts.lineTrans || 0 } });
  slide.addText(text, { x: x + 0.05, y: y + 0.045, w: w - 0.1, h: 0.09, fontSize: opts.fontSize || 6.2, bold: true, color: opts.textColor || 'FFFFFF', align: 'center', margin: 0, fit: 'shrink' });
}

function labOf(model) {
  const m = model.toLowerCase();
  if (m.includes('gpt') || m.includes('codex') || m.includes('o3')) return 'OpenAI';
  if (m.includes('gemini')) return 'Google';
  if (m.includes('claude') || m.includes('opus') || m.includes('sonnet')) return 'Anthropic';
  if (m.includes('muse')) return 'Muse';
  return 'Other';
}

function addLegend(slide, x, y, labs=['OpenAI','Google','Anthropic','Muse']) {
  labs.forEach((lab, i) => {
    slide.addShape(pptx.ShapeType.rect, { x: x + i*1.1, y, w: 0.12, h: 0.12, fill: { color: labColors[lab] }, line: { color: labColors[lab] } });
    slide.addText(lab, { x: x + i*1.1 + 0.16, y: y - 0.005, w: 0.8, h: 0.12, fontSize: 7.2, color: C.muted, margin: 0 });
  });
}

function bar(slide, x, y, w, h, value, max, color, label, score, opts={}) {
  const bw = Math.max(0.02, w * value / max);
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.03, fill: { color: 'E8EEF7' }, line: { color: 'E8EEF7' } });
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w: bw, h, rectRadius: 0.03, fill: { color }, line: { color } });
  slide.addText(label, { x: opts.labelX || (x - 1.95), y: y - 0.01, w: opts.labelW || 1.75, h: h + 0.05, fontSize: opts.fontSize || 7.4, color: C.text, bold: opts.bold || false, margin: 0, fit: 'shrink' });
  slide.addText(score, { x: x + w + 0.12, y: y - 0.01, w: opts.scoreW || 0.8, h: h + 0.05, fontSize: opts.fontSize || 7.4, color: C.text, bold: true, margin: 0 });
}

function stat(slide, x, y, num, label, color=C.cyan, sub='') {
  slide.addText(num, { x, y, w: 1.8, h: 0.48, fontSize: 25, bold: true, color, fontFace: 'Trebuchet MS', margin: 0 });
  slide.addText(label, { x, y: y+0.53, w: 2.0, h: 0.25, fontSize: 8.5, color: 'D9E4FF', bold: true, margin: 0 });
  if (sub) slide.addText(sub, { x, y: y+0.80, w: 2.4, h: 0.3, fontSize: 7.2, color: 'AFC0E8', margin: 0 });
}

function addWrappedText(slide, text, x, y, w, h, opts={}) {
  slide.addText(text, { x, y, w, h, fontSize: opts.fontSize || 9, color: opts.color || C.text, bold: opts.bold || false, margin: opts.margin ?? 0.04, breakLine: false, fit: 'shrink', valign: opts.valign || 'top' });
}

